import TextArea from "./text-area";
import { Meta, StoryObj } from "@storybook/react";
import { fn } from "storybook/test";
import { useState } from "react";
import { Form, FormField, buildField, useForm } from "../../../helpers/form-builder";

const meta = {
  title: "Primitives/Form Fields/Text Area",
  component: TextArea,
  argTypes: {
    // Component-specific props
    label: { control: "text" },
    placeholder: { control: "text" },
    helperText: { control: "text" },
    focus: { control: "boolean" },
    error: { control: "text" },
    isValid: { control: "boolean" },
    isDisabled: { control: "boolean" },
    isRequired: { control: "boolean" },
    resizable: { control: "boolean" },
    isEditable: { control: "boolean" },
    className: { control: "text" },
    inputClassName: { control: "text" },
    formField: { control: false },
    // Native textarea props we expose commonly
    autoComplete: { control: { type: "radio" }, options: ["on", "off"] },
    minLength: { control: "number" },
    maxLength: { control: "number" },
    rows: { control: "number" },
  },
  args: { onChange: fn() },
} satisfies Meta<typeof TextArea>;

export default meta;

type Story = StoryObj<typeof meta>;

export const NonFormTextArea: Story = {
  args: {
    label: "Meddelande",
    placeholder: "Skriv ditt meddelande här...",
    helperText: "",
    focus: false,
    error: "",
    isValid: true,
    isDisabled: false,
    isRequired: false,
    resizable: false,
    isEditable: true,
    autoComplete: "on",
    minLength: 0,
    maxLength: 2000,
    rows: 5,
    className: "",
    inputClassName: "",
  },
  render: function StoryComponent({ ...args }) {
    const [state, setState] = useState("");
    const { onChange, value, ...restArgs } = args;

    const updateTextArea = (name: string, value: string) => {
      setState(value);
    };

    return (
      <div style={{ padding: "1rem" }}>
        <TextArea onChange={updateTextArea} value={state} {...restArgs} />
      </div>
    );
  },
};

const fieldKey = "message";

const initialForm: Form = {
  fields: new Map<string, FormField>([["message", buildField(fieldKey, { type: "TEXT_AREA" })]]),
};

const createFormStory = (args: Story["args"]): Story => ({
  args,
  render: function StoryComponent({ ...args }) {
    const [form, , handleFieldOnChange] = useForm(initialForm);
    // Remove 'onChange' from args to avoid duplicate prop
    const { onChange, ...restArgs } = args;

    return (
      <div style={{ padding: "1rem" }}>
        {form.fields.get(fieldKey) && (
          <TextArea formField={form.fields.get(fieldKey)} onChange={handleFieldOnChange} {...restArgs} />
        )}
      </div>
    );
  },
});

export const Primary: Story = createFormStory({
  label: "Meddelande",
  placeholder: "Skriv ditt meddelande här...",
  helperText: "",
  focus: false,
  error: "",
  isValid: undefined,
  isDisabled: false,
  isRequired: false,
  resizable: false,
  isEditable: true,
  autoComplete: "on",
  minLength: 0,
  maxLength: 2000,
  rows: 5,
  className: "",
  inputClassName: "",
});

export const Required: Story = createFormStory({
  ...Primary.args,
  isRequired: true,
});

export const HelperText: Story = createFormStory({
  ...Primary.args,
  helperText: "Beskriv ditt ärende så detaljerat som möjligt.",
});

export const Error: Story = createFormStory({
  ...Primary.args,
  isValid: false,
  error: "Detta fält är obligatoriskt",
});

export const HelperTextWithError: Story = createFormStory({
  ...Primary.args,
  helperText: "Beskriv ditt ärende så detaljerat som möjligt.",
  isRequired: true,
  isValid: false,
});

export const Disabled: Story = createFormStory({
  ...Primary.args,
  isDisabled: true,
});
